tools:
cd multicode/obelisk/full; python3 -I - <<'E'
p='core/suits.mjs'
s=open(p).read()
s=s.replace("// Код по спеке oracle/specs/suits-a.md (правила 1–7).","// Код по спеке oracle/specs/suits-a.md (правила 1–12).")
s=s.replace("  const effects = tableRows(suitsData.tables.effects);\n","  const effects = tableRows(suitsData.tables.effects);\n  const abilities = tableRows(suitsData.tables.abilities);\n\n  function ability(suit, kind) {\n    return abilities.find((a) => a.suit === suit && a.kind === kind);\n  }\n")
s=s.replace("  return { worn, fueled, apply };","""  // правило 9: раз в periodFrames кадров бомба стреляет, если зарядов не меньше капа
  function autobomb(suit, frame, charges, caps) {
    const a = ability(suit, 'autobomb');
    if (!a || frame <= 0 || frame % C['autobomb.periodFrames'] !== 0) return -1;
    return charges[a.bomb] >= caps[a.bomb] ? a.bomb : -1;
  }

  // правило 10: период бомбы лягушки в кадрах
  function frogPeriod(upgrade) {
    return C['frog.baseFrames'] - C['frog.stepFrames'] * upgrade;
  }

  function frogFires(suit, frame, upgrade) {
    if (!ability(suit, 'frogBomb') || frame <= 0) return false;
    return frame % frogPeriod(upgrade) === 0;
  }

  // правило 11: золото + доля · цена продажи (сначала произведение)
  function midasGold(gold, ratio, sell) {
    return gold + ratio * sell;
  }

  return { worn, fueled, apply, autobomb, frogPeriod, frogFires, midasGold };""")
open(p,'w').write(s)
E
node oracle/suits819/checkplay819.mjs | tail -3; node oracle/suits819/check819.mjs --all | tail -2; node --test tests/suits819.test.mjs 2>&1 | grep -E "^# (pass|fail)"; node tests/guards/run.mjs | tail -2
